'use client';

import { useMemo, useState } from 'react';
import Link from 'next/link';
import { Inter, Space_Grotesk } from 'next/font/google';
import { FaArrowLeft, FaMoneyBillTrendUp, FaTruckMoving, FaUserPlus, FaWallet } from 'react-icons/fa6';

import { routePreferences, truckTypes } from '@/lib/demo-data';
import { addDriver, addTruck, loadDemoStore, loginUser, markBookingPaid, signUpUser } from '@/lib/demo-store';

const heading = Space_Grotesk({ subsets: ['latin'], weight: ['500', '700'] });
const body = Inter({ subsets: ['latin'], weight: ['400', '500', '600'] });

type OwnerSession = {
  id: string;
  name: string;
  email: string;
  companyName?: string;
};

export default function FleetPortal() {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [store, setStore] = useState(() => loadDemoStore());
  const [session, setSession] = useState<OwnerSession | null>(null);
  const [message, setMessage] = useState('');
  const [authForm, setAuthForm] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
    region: 'Delhi NCR',
    companyName: '',
  });
  const [truckForm, setTruckForm] = useState({
    registrationNumber: '',
    truckType: 'Mini Truck',
    capacityTons: '1.5',
    region: 'Delhi NCR',
  });
  const [driverForm, setDriverForm] = useState({
    name: '',
    email: '',
    password: 'DriverDemo123!',
    phone: '',
    region: 'Delhi NCR',
    truckId: '',
    rating: '4.5',
    predictedRating: '4.4',
    points: '180',
    trips: '60',
    fixedIncome: '5200',
    etaHours: '3',
    safetyNote: 'Verified documents and careful goods handling.',
    routePreference: 'Both',
  });

  const ownerTrucks = useMemo(() => {
    if (!session) return [];
    return store.trucks.filter((truck) => truck.ownerId === session.id);
  }, [store, session]);
  const ownerDrivers = useMemo(() => {
    if (!session) return [];
    return store.drivers.filter((driver) => driver.ownerId === session.id);
  }, [store, session]);
  const ownerBookings = useMemo(() => {
    if (!session) return [];
    return store.bookings.filter((booking) => booking.ownerId === session.id);
  }, [store, session]);

  const incomeReport = useMemo(() => {
    const paid = ownerBookings.filter((booking) => booking.paid);
    const pending = ownerBookings.filter((booking) => !booking.paid);
    return {
      paidRevenue: paid.reduce((sum, booking) => sum + booking.amount, 0),
      pendingRevenue: pending.reduce((sum, booking) => sum + booking.amount, 0),
      completedTrips: paid.length,
    };
  }, [ownerBookings]);

  const handleAuth = () => {
    try {
      if (mode === 'signup') {
        const { user } = signUpUser({
          role: 'fleet_owner',
          name: authForm.name,
          email: authForm.email,
          password: authForm.password,
          phone: authForm.phone,
          region: authForm.region,
          companyName: authForm.companyName,
        });
        setSession({ id: user.id, name: user.name, email: user.email, companyName: user.companyName });
        setMessage('Fleet owner account created.');
      } else {
        const { user } = loginUser(authForm.email, authForm.password, 'fleet_owner');
        setSession({ id: user.id, name: user.name, email: user.email, companyName: user.companyName });
        setMessage('Logged in as fleet owner.');
      }
      setStore(loadDemoStore());
    } catch (error) {
      setMessage(error instanceof Error ? error.message : 'Unable to continue.');
    }
  };

  const handleAddTruck = () => {
    if (!session) return;
    addTruck({
      ownerId: session.id,
      registrationNumber: truckForm.registrationNumber,
      truckType: truckForm.truckType,
      capacityTons: Number(truckForm.capacityTons),
      region: truckForm.region,
    });
    setMessage('Truck added successfully.');
    setStore(loadDemoStore());
    setTruckForm({ ...truckForm, registrationNumber: '' });
  };

  const handleAddDriver = () => {
    if (!session || !driverForm.truckId) {
      setMessage('Select a truck for the driver.');
      return;
    }
    addDriver({
      ownerId: session.id,
      name: driverForm.name,
      email: driverForm.email,
      password: driverForm.password,
      phone: driverForm.phone,
      region: driverForm.region,
      truckId: driverForm.truckId,
      rating: Number(driverForm.rating),
      predictedRating: Number(driverForm.predictedRating),
      points: Number(driverForm.points),
      trips: Number(driverForm.trips),
      fixedIncome: Number(driverForm.fixedIncome),
      etaHours: Number(driverForm.etaHours),
      safetyNote: driverForm.safetyNote,
      routePreference: driverForm.routePreference,
    });
    setMessage('Driver added to fleet.');
    setStore(loadDemoStore());
    setDriverForm({ ...driverForm, name: '', email: '', phone: '' });
  };

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top_left,_rgba(249,115,22,0.18),_transparent_28%),linear-gradient(180deg,_#1c1917_0%,_#111827_45%,_#020617_100%)] text-white">
      <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
        <div className="mb-8 flex items-center justify-between">
          <Link href="/get-started" className={`${body.className} inline-flex items-center gap-3 text-sm text-slate-300 transition hover:text-orange-300`}>
            <FaArrowLeft className="h-4 w-4" />
            Back to roles
          </Link>
          <div className={`${body.className} rounded-full border border-white/10 bg-white/5 px-4 py-2 text-sm text-slate-200`}>
            Working fleet owner operations demo
          </div>
        </div>

        <section className="grid gap-6 lg:grid-cols-[0.88fr_1.12fr]">
          <div className="rounded-[30px] border border-white/10 bg-white/5 p-8 backdrop-blur">
            <p className={`${body.className} mb-3 text-sm uppercase tracking-[0.2em] text-orange-200/80`}>Fleet owner portal</p>
            <h1 className={`${heading.className} text-4xl font-bold leading-tight`}>
              Log in as a fleet owner, register trucks, add drivers, and track income after payments clear.
            </h1>
            <p className={`${body.className} mt-4 text-sm text-slate-300`}>
              This owner side now supports sign up and login, truck entry, driver entry, and revenue tracking from completed paid bookings.
            </p>

            {!session ? (
              <div className="mt-8 rounded-[28px] border border-white/10 bg-slate-950/60 p-6">
                <div className="mb-4 flex gap-2">
                  <button onClick={() => setMode('login')} className={`rounded-full px-4 py-2 text-sm ${mode === 'login' ? 'bg-orange-400 text-slate-950' : 'bg-white/5 text-slate-300'}`}>Login</button>
                  <button onClick={() => setMode('signup')} className={`rounded-full px-4 py-2 text-sm ${mode === 'signup' ? 'bg-orange-400 text-slate-950' : 'bg-white/5 text-slate-300'}`}>Sign up</button>
                </div>
                <div className="grid gap-4">
                  {mode === 'signup' && (
                    <>
                      <input value={authForm.name} onChange={(e) => setAuthForm({ ...authForm, name: e.target.value })} placeholder="Owner name" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                      <input value={authForm.companyName} onChange={(e) => setAuthForm({ ...authForm, companyName: e.target.value })} placeholder="Company name" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                      <input value={authForm.phone} onChange={(e) => setAuthForm({ ...authForm, phone: e.target.value })} placeholder="Phone" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                      <input value={authForm.region} onChange={(e) => setAuthForm({ ...authForm, region: e.target.value })} placeholder="Region" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                    </>
                  )}
                  <input value={authForm.email} onChange={(e) => setAuthForm({ ...authForm, email: e.target.value })} placeholder="Email" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                  <input value={authForm.password} onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })} placeholder="Password" type="password" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                  <button onClick={handleAuth} className="rounded-2xl bg-orange-400 px-4 py-3 font-semibold text-slate-950">
                    {mode === 'signup' ? 'Create fleet owner account' : 'Log in as fleet owner'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="mt-8 rounded-[28px] border border-emerald-300/20 bg-emerald-400/5 p-6">
                <div className={`${heading.className} text-2xl font-semibold`}>{session.companyName || session.name}</div>
                <p className={`${body.className} mt-2 text-sm text-slate-300`}>Logged in as {session.email}. Add fleet data and review payments below.</p>
              </div>
            )}

            {message && <div className={`${body.className} mt-4 rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm text-slate-200`}>{message}</div>}
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <div className="rounded-[28px] border border-white/10 bg-white/5 p-6">
              <FaWallet className="mb-3 h-5 w-5 text-orange-300" />
              <div className={`${body.className} text-sm text-slate-300`}>Paid revenue</div>
              <div className={`${heading.className} mt-2 text-3xl font-semibold`}>Rs. {incomeReport.paidRevenue.toLocaleString()}</div>
            </div>
            <div className="rounded-[28px] border border-white/10 bg-white/5 p-6">
              <FaMoneyBillTrendUp className="mb-3 h-5 w-5 text-orange-300" />
              <div className={`${body.className} text-sm text-slate-300`}>Pending revenue</div>
              <div className={`${heading.className} mt-2 text-3xl font-semibold`}>Rs. {incomeReport.pendingRevenue.toLocaleString()}</div>
            </div>
            <div className="rounded-[28px] border border-white/10 bg-white/5 p-6">
              <FaTruckMoving className="mb-3 h-5 w-5 text-orange-300" />
              <div className={`${body.className} text-sm text-slate-300`}>Completed paid trips</div>
              <div className={`${heading.className} mt-2 text-3xl font-semibold`}>{incomeReport.completedTrips}</div>
            </div>
          </div>
        </section>

        {session && (
          <section className="mt-8 grid gap-6 xl:grid-cols-[1fr_1fr]">
            <div className="rounded-[30px] border border-white/10 bg-white/5 p-8 backdrop-blur">
              <h2 className={`${heading.className} text-3xl font-semibold`}>Add truck details</h2>
              <div className="mt-6 grid gap-4">
                <input value={truckForm.registrationNumber} onChange={(e) => setTruckForm({ ...truckForm, registrationNumber: e.target.value })} placeholder="Registration number" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <select value={truckForm.truckType} onChange={(e) => setTruckForm({ ...truckForm, truckType: e.target.value })} className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3">
                  {truckTypes.map((type) => <option key={type} value={type}>{type}</option>)}
                </select>
                <input value={truckForm.capacityTons} onChange={(e) => setTruckForm({ ...truckForm, capacityTons: e.target.value })} placeholder="Capacity in tons" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <input value={truckForm.region} onChange={(e) => setTruckForm({ ...truckForm, region: e.target.value })} placeholder="Operating region" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <button onClick={handleAddTruck} className="rounded-2xl bg-orange-400 px-4 py-3 font-semibold text-slate-950">Add truck</button>
              </div>

              <div className="mt-6 space-y-3">
                {ownerTrucks.map((truck) => (
                  <div key={truck.id} className="rounded-2xl border border-white/10 bg-slate-950/50 p-4">
                    <div className={`${heading.className} text-lg font-semibold`}>{truck.registrationNumber}</div>
                    <div className={`${body.className} mt-1 text-sm text-slate-300`}>{truck.truckType} • {truck.capacityTons} tons • {truck.region}</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="rounded-[30px] border border-white/10 bg-slate-950/70 p-8">
              <div className="flex items-center gap-3">
                <FaUserPlus className="h-5 w-5 text-orange-300" />
                <h2 className={`${heading.className} text-3xl font-semibold`}>Add fleet driver</h2>
              </div>
              <div className="mt-6 grid gap-4">
                <input value={driverForm.name} onChange={(e) => setDriverForm({ ...driverForm, name: e.target.value })} placeholder="Driver name" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <input value={driverForm.email} onChange={(e) => setDriverForm({ ...driverForm, email: e.target.value })} placeholder="Driver email" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <input value={driverForm.phone} onChange={(e) => setDriverForm({ ...driverForm, phone: e.target.value })} placeholder="Driver phone" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <select value={driverForm.truckId} onChange={(e) => setDriverForm({ ...driverForm, truckId: e.target.value })} className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3">
                  <option value="">Assign truck</option>
                  {ownerTrucks.map((truck) => <option key={truck.id} value={truck.id}>{truck.registrationNumber} • {truck.truckType}</option>)}
                </select>
                <select value={driverForm.routePreference} onChange={(e) => setDriverForm({ ...driverForm, routePreference: e.target.value })} className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3">
                  {routePreferences.map((route) => <option key={route} value={route}>{route}</option>)}
                </select>
                <input value={driverForm.fixedIncome} onChange={(e) => setDriverForm({ ...driverForm, fixedIncome: e.target.value })} placeholder="Fixed driver income" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <textarea value={driverForm.safetyNote} onChange={(e) => setDriverForm({ ...driverForm, safetyNote: e.target.value })} placeholder="Safety note" className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3" />
                <button onClick={handleAddDriver} className="rounded-2xl bg-orange-400 px-4 py-3 font-semibold text-slate-950">Add driver</button>
              </div>
            </div>
          </section>
        )}

        {session && (
          <section className="mt-8 rounded-[30px] border border-white/10 bg-white/5 p-8 backdrop-blur">
            <h2 className={`${heading.className} text-3xl font-semibold`}>Income reports and payments</h2>
            <div className="mt-6 space-y-4">
              {ownerBookings.map((booking) => (
                <div key={booking.id} className="rounded-3xl border border-white/10 bg-slate-950/50 p-5">
                  <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                    <div>
                      <div className={`${heading.className} text-xl font-semibold`}>{booking.from} to {booking.to}</div>
                      <div className={`${body.className} mt-1 text-sm text-slate-300`}>{booking.truckType} • {booking.loadType} • {booking.pickupTime}</div>
                    </div>
                    <div className={`${body.className} flex flex-wrap gap-2 text-sm`}>
                      <span className="rounded-full bg-amber-400/10 px-3 py-1 text-amber-100">Rs. {booking.amount.toLocaleString()}</span>
                      <span className={`rounded-full px-3 py-1 ${booking.paid ? 'bg-emerald-400/10 text-emerald-100' : 'bg-rose-400/10 text-rose-100'}`}>
                        {booking.paid ? 'Paid' : 'Pending payment'}
                      </span>
                    </div>
                  </div>
                  {!booking.paid && (
                    <button
                      onClick={() => {
                        markBookingPaid(booking.id);
                        setStore(loadDemoStore());
                        setMessage('Payment marked complete and income report updated.');
                      }}
                      className="mt-4 rounded-2xl bg-emerald-400 px-4 py-2 font-semibold text-slate-950"
                    >
                      Mark payment complete
                    </button>
                  )}
                </div>
              ))}
            </div>

            <div className="mt-8 rounded-[28px] border border-white/10 bg-slate-950/60 p-6">
              <h3 className={`${heading.className} text-2xl font-semibold`}>Fleet drivers</h3>
              <div className="mt-4 grid gap-4 md:grid-cols-2">
                {ownerDrivers.map((driver) => {
                  const user = store.users.find((item) => item.id === driver.userId);
                  const truck = store.trucks.find((item) => item.id === driver.truckId);
                  return (
                    <div key={driver.id} className="rounded-2xl border border-white/10 bg-white/5 p-4">
                      <div className={`${heading.className} text-lg font-semibold`}>{user?.name}</div>
                      <div className={`${body.className} mt-2 text-sm text-slate-300`}>{truck?.registrationNumber} • {driver.routePreference} • Rs. {driver.fixedIncome.toLocaleString()}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
}
